import { describe, it, expect } from 'vitest';
import { parseGcodeMetadata } from './gcodeParser';

describe('parseGcodeMetadata', () => {
    it('extrai gramas e tempo de Bambu Studio / OrcaSlicer (inclusive multi-cor)', () => {
        const sample = `
; generated by BambuStudio 01.09.03.50
; model printing time: 1h 12m 10s; total estimated time: 1h 17m 20s
; filament used [g] = 12.40, 3.66
; total filament used [g] = 16.06
G28
`;
        const parsed = parseGcodeMetadata(sample, 'mario_mao_zelda.gcode');
        expect(parsed.slicerName).toBe('Bambu Studio');
        expect(parsed.weightG).toBeCloseTo(16.06, 2);
        expect(parsed.printHours).toBe(1);
        expect(parsed.printMinutes).toBe(17);
        expect(parsed.suggestedProjectName).toBe('mario mao zelda');
    });

    it('extrai tempo com dias no PrusaSlicer / SuperSlicer', () => {
        const sample = `
; generated by PrusaSlicer 2.8.0
; filament used [g] = 145.5, 54.5
; estimated printing time (normal mode) = 1d 2h 15m 10s
`;
        const parsed = parseGcodeMetadata(sample);
        expect(parsed.slicerName).toBe('PrusaSlicer');
        expect(parsed.weightG).toBeCloseTo(200, 2);
        expect(parsed.printHours).toBe(26);
        expect(parsed.printMinutes).toBe(15);
    });

    it('extrai tempo em segundos e converte metros no Ultimaker Cura', () => {
        const sample = `
;FLAVOR:Marlin
;TIME:4620
;Filament used: 5.39m
;Generated with Cura_SteamEngine 5.7.0
`;
        const parsed = parseGcodeMetadata(sample);
        expect(parsed.slicerName).toBe('Cura');
        expect(parsed.printHours).toBe(1);
        expect(parsed.printMinutes).toBe(17);
        expect(parsed.weightG).toBeCloseTo(16.06, 1);
    });

    it('extrai formato do Snapmaker Luban', () => {
        const sample = `
;Generated by Snapmaker Luban 4.13.0
;total_time = 5400
;filament_used_g = 42.8
`;
        const parsed = parseGcodeMetadata(sample);
        expect(parsed.slicerName).toBe('Snapmaker Luban');
        expect(parsed.printHours).toBe(1);
        expect(parsed.printMinutes).toBe(30);
        expect(parsed.weightG).toBeCloseTo(42.8, 2);
    });

    it('regressão: extrai ;TIME:3600 (1h exact) no formato Cura e ignora entradas vazias/corrompidas sem exceção', () => {
        const exactHour = parseGcodeMetadata(';FLAVOR:Marlin\n;TIME:3600\nG28\n');
        expect(exactHour.printHours).toBe(1);
        expect(exactHour.printMinutes).toBe(0);

        const empty = parseGcodeMetadata('');
        expect(empty.weightG).toBeNull();
        expect(empty.printHours).toBe(0);
        expect(empty.printMinutes).toBe(0);
        expect(empty.totalMinutes).toBe(0);
        expect(empty.slicerName).toBeUndefined();

        const garbage = parseGcodeMetadata('corrupted %%% binary \0\0 not-gcode', 'teste_arquivo.gcode');
        expect(garbage.weightG).toBeNull();
        expect(garbage.suggestedProjectName).toBe('teste arquivo');
    });
});
